154					filtered, audit, filterErr := filterFactsByTemporalEligibility(allFacts, dates, eligibleBefore, excludeSessionIDs)
155					if filterErr != nil {
156						return filterErr
157					}
158					candidateFacts = filtered
159					eligibility = &audit
160				}
161				facts := factstore.FilterByLocus(factstore.FilterByKind(factstore.FilterByScope(candidateFacts, scope), kind), locus)
162				effectiveQuery := query
163				if expand && strings.TrimSpace(query) != "" {
164					resolved := agent
165					if resolved == "auto" {
166						resolved = cfg.Deps.DefaultRefreshAgent(cmd.Context(), cfg.Options.Runner, repoDir)
167					}
168					expanded, expErr := cfg.Deps.ExpandQuery(cmd.Context(), resolved, agentCommand, model, repoDir, query)
169					if expErr != nil {
170						return expErr
171					}
172					effectiveQuery = expanded
173				}
174				// --no-semantic and --read-only-semantic-cache are vacuously
175				// satisfied since the semantic arm was removed (trail #278):
176				// ranking is always lexical and no vector cache exists to write.
177				_, _ = noSemantic, readOnlySemanticCache
178				matches := cfg.Deps.RankFacts(facts, effectiveQuery, limit, includeAll)
179				// Locus drift (Phase 2 item 4): flag surfaced facts whose code
180				// locus left the worktree, so the agent knows which to re-verify.
181				drift := retrieval.FactsLocusDrift(repoDir, retrieval.FactsEligibleForLocusDrift(matches, globalIDs))
182				recordReceipt := func() {
183					cfg.Deps.RecordServedFacts(cmd.ErrOrStderr(), cmd.Context(), cfg.Options, brainDir, resolvedBranch, "recall",
184						repoDir, query, matches)
185				}
186				if jsonOut {
187					// Recall's JSON envelope is fact-centric (top-level `facts`), so
188					// its fact-scoped keys stay unprefixed: `pending_reviews` and
189					// `locus_drift`. The brief report is a multi-domain object and
190					// prefixes the same concepts as `facts_pending_review` /
191					// `facts_locus_drift` to disambiguate. This per-surface split is
192					// intentional and kept as-is; we do not unify the keys.
193					out := map[string]any{"query": query, "facts": matches}
194					if branch != "" {
195						out["branch"] = branch
196					}
197					// A consumer that renders these has to be able to tell which
198					// facts came from outside this repository; the ids are the
199					// smallest way to say so without changing the fact shape that
200					// every existing reader binds to.
201					if ids := SortedGlobalFactIDs(matches, globalIDs); len(ids) > 0 {
202						out["global_fact_ids"] = ids
203					}
204					engine := recallRetrievalIdentity()
205					out["retrieval_engine"] = engine
206					if engine.EffectiveEngine != "" {
207						out["effective_engine"] = engine.EffectiveEngine
208					}
209					if eligibility != nil {
210						eligibility.DeliveredCount = len(matches)
211						out["eligibility"] = eligibility
212					}
213					if len(drift) > 0 {
214						out["locus_drift"] = drift
215					}
216					if storeWarning != "" {
217						warnings, _ := out["warnings"].([]string)
218						out["warnings"] = append(warnings, storeWarning)
219					}
220					if len(matches) == 0 {
221						if note := cfg.Deps.EmptyResultBlindSpot(brainDir, resolvedBranch); note != "" && storeWarning == "" {
222							out["blind_spot"] = note
223						}
224					}
225					if err := cmdutil.WriteJSON(cmd, out); err != nil {
226						return err
227					}
228					if len(matches) > 0 {
229						recordReceipt()
230					}
231					return nil
232				}
233				if len(matches) == 0 {
234					return cmdutil.WriteText(cmd, func(out io.Writer) {
235						if branch != "" {
236							fmt.Fprintf(out, "no memories for %q stamped %s\n", query, branch)
237						} else {
238							fmt.Fprintf(out, "no memories for %q\n", query)
239						}
240						if storeWarning != "" {
241							fmt.Fprintln(out, "warning: "+storeWarning)
242						}
243						if note := cfg.Deps.EmptyResultBlindSpot(brainDir, resolvedBranch); note != "" && storeWarning == "" {
244							fmt.Fprintln(out, note)
245						}
246					})
247				}
248				if err := cmdutil.WriteText(cmd, func(out io.Writer) {
249					if storeWarning != "" {
250						fmt.Fprintln(out, "warning: "+storeWarning)
251					}
252					for _, f := range matches {
253						if globalIDs[f.ID] {
254							// Without this a global convention is indistinguishable
255							// from something this repository declared, and an agent
256							// would cite it as a property of the codebase.
257							PrintGlobalFactLine(out, f)
258						} else {
259							PrintFactLine(out, f)
260						}
261						if gone := drift[f.ID]; len(gone) > 0 {
262							fmt.Fprintf(out, "  ⚠ stale locus (no longer in worktree): %s\n", strings.Join(gone, ", "))
263						}
264					}
265				}); err != nil {
266					return err
267				}
268				recordReceipt()
269				return nil
270			},
271		}
