294	// PrintGlobalFactLine renders a fact that came from the global store rather than
295	// this repository.
296	func PrintGlobalFactLine(out io.Writer, f factmerge.Record) {
297		marker := ""
298		switch f.Status {
299		case factmerge.StatusSuperseded:
300			marker = " (superseded)"
301		case factmerge.StatusRetracted:
302			marker = " (retracted)"
303		}
304		fmt.Fprintf(out, "%s %s [%s] (global)%s\n  %s\n", f.ID, factstore.KindOrInferred(f), strings.Join(f.Paths, ","), marker, f.Text)
305	}
306	
307	// SortedGlobalFactIDs returns the ids of the surfaced facts that are global, in
308	// the order they were surfaced, so JSON output is stable across runs.
309	func SortedGlobalFactIDs(matches []factmerge.Record, globalIDs map[string]bool) []string {
310		var ids []string
311		for _, f := range matches {
312			if globalIDs[f.ID] {
313				ids = append(ids, f.ID)
314			}
315		}
316		return ids
317	}
318	
319	// PrintFactLine renders a fact for human-readable listings.
320	func PrintFactLine(out io.Writer, f factmerge.Record) {
321		marker := ""
322		switch f.Status {
323		case factmerge.StatusSuperseded:
324			marker = " (superseded)"
325		case factmerge.StatusRetracted:
326			marker = " (retracted)"
327		}
328		fmt.Fprintf(out, "%s %s [%s]%s\n  %s\n", f.ID, factstore.KindOrInferred(f), strings.Join(f.Paths, ","), marker, f.Text)
329	}
