1460	func runBrainBrief(ctx context.Context, cmd *cobra.Command, opts Options, briefOpts brainBriefOptions, task string) error {
1461		if briefOpts.limit <= 0 {
1462			return errors.New("--limit must be greater than zero")
1463		}
1464		var profile *brainBriefProfile
1465		if briefOpts.profileJSON != "" {
1466			profile = newBrainBriefProfiler()
1467		}
1468		target := agentSurfaceTarget(opts, nil)
1469		statusStarted := profile.start()
1470		status, err := buildBrainStatusReport(ctx, opts, target)
1471		statusErrors := 0
1472		if err != nil {
1473			statusErrors = 1
1474		}
1475		if profile != nil {
1476			statusOutputs := 1
1477			if err != nil {
1478				statusOutputs = 0
1479			}
1480			profile.finishStage(&profile.StatusBuildState, statusStarted, 1, statusOutputs, statusErrors)
1481		}
1482		if err != nil {
1483			return err
1484		}
1485		report := brainBriefReport{
1486			GeneratedAt: opts.Now().UTC(),
1487			Task:        task,
1488			Status:      brainBriefOutputStatus(status),
1489			Guidance: []string{
1490				"Treat the brain as an indexed snapshot, not live memory.",
1491				"Use likely_edit_files before text search; if search is still needed, scope it to likely_files and specific identifiers. Use likely_test_files for validation context.",
1492				"Use the live-state overlay before trusting code-context results for files changed in this session.",
1493				"Inspect full diffs or source files when the task intersects dirty files or when confidence is low.",
1494			},
1495		}
1496		var receiptBranch, receiptSurface string
1497		var receiptFactIDs []string
1498		// The graph plugin's store answers first (COR-2217): `graph context` reads
1499		// the committed-tree sqlite sidecar the graph owns, so the brief no longer
1500		// depends on the brain's own copy of the snapshot when the plugin can
1501		// serve. Plugin absent or a version without the verb falls through to the
1502		// internal semantic path (or its missing-index warning) unchanged; a
1503		// present graph with no store for this commit keeps its detail so the
1504		// warning can carry graph's remedy instead of stale `refresh` advice
1505		// (COR-2257).
1506		semanticDelegated := false
1507		graphStoreMissing := false
1508		var graphStoreMissingDetail string
1509		{
1510			delegationStarted := profile.start()
1511			graphContext, graphErr := fetchGraphTaskContext(ctx, opts.Runner, status.Repo.Root, briefOpts.graphBinary, task, briefOpts.limit, briefOpts.limit)
1512			if graphErr == nil && graphContext.StoreUnavailable {
1513				graphStoreMissing = true
1514				graphStoreMissingDetail = strings.TrimSpace(graphContext.Detail)
1515			}
1516			// An empty symbol list falls through too: the internal index may still
1517			// have an answer, and delegating nothing would also suppress the
1518			// missing-index warning. Commit/tree coherence needs no check here —
1519			// the provider keys the store by the current committed tree and
1520			// reports any mismatch as store_unavailable.
1521			// An ancestor answer whose own account of itself is inconsistent is
1522			// refused outright: brain would be unable to say which results are
1523			// incomplete, which is the only reason to accept one at all. Falling
1524			// through here lands on the internal semantic path, i.e. exactly what
1525			// happens with no graph plugin.
1526			if graphErr == nil && !graphContext.Stale.usable() {
1527				graphContext = graphTaskContext{}
1528				graphStoreMissing = true
1529				graphStoreMissingDetail = "graph answered from an ancestor commit but could not say which files it excluded; ignoring it"
1530			}
1531			if graphErr == nil && !graphContext.StoreUnavailable && len(graphContext.Symbols) > 0 {
1532				report.Semantic.Context = semanticContextResult{
1533					Symbols:   nonNil(graphContextSymbolRecords(graphContext.Symbols)),
1534					Relations: nonNil(graphContextRelationRecords(graphContext.Symbols, graphContext.Relations)),
1535				}
1536				report.Semantic.Tests = graphContextTestsResult(graphContext.Tests)
1537				report.Semantic.Source = "graph-context"
1538				report.Semantic.Staleness = semanticStalenessFor(graphContext.Stale, graphContext.Symbols, graphContext.Tests)
1539				semanticDelegated = true
1540				if profile != nil {
1541					outputs := len(graphContext.Symbols) + len(graphContext.Relations) + len(graphContext.Tests)
1542					profile.finishStage(&profile.Semantic.Context, delegationStarted, len(graphContext.Symbols), outputs, 0)
1543				}
1544			}
1545		}
1546		if status.Manifest != nil && status.Manifest.Sources != nil && status.Manifest.Sources.Semantic != nil {
1547			semanticSource := status.Manifest.Sources.Semantic
1548			semanticInputCount := semanticSource.Symbols + semanticSource.Relations
1549			semanticLimit := briefOpts.limit
1550			if brainBriefSemanticNeedsCurrentBoundary(report.Status) {
1551				// A bounded overfetch lets the current-worktree boundary refill slots
1552				// which stale top-ranked records would otherwise consume.
1553				semanticLimit = brainBriefSemanticCandidateLimit(briefOpts.limit, semanticSource.Symbols)
1554			}
1555			if !semanticDelegated {
1556				contextStarted := profile.start()
1557				contextSymbols, contextRelations, contextNeighbors, contextErr := semstore.ContextFacts(status.Brain.Path, semanticSource, task, semanticLimit, 0)
1558				if contextErr != nil {
1559					report.Warnings = append(report.Warnings, "code context unavailable: "+contextErr.Error())
1560				} else {
1561					report.Semantic.Context = brainBriefSelectSemanticContext(contextSymbols, contextRelations, contextNeighbors, task, semanticLimit)
1562					if len(report.Semantic.Context.Symbols) > 0 {
1563						impactLimit := max(40, brainBriefExpandedCandidateLimit(briefOpts.limit, 8))
1564						_, impactSymbols, impactRelations, impactErr := semstore.ImpactFacts(status.Brain.Path, status.Manifest.Sources.Semantic, report.Semantic.Context.Symbols[0].ID, 2, impactLimit)
1565						if impactErr != nil {
1566							report.Warnings = append(report.Warnings, "code context impact unavailable: "+impactErr.Error())
1567						} else {
1568							report.Semantic.Context = brainBriefMergeImpactContext(report.Semantic.Context, impactSymbols, impactRelations, task, briefOpts.limit)
1569						}
1570					}
1571				}
1572				if profile != nil {
1573					contextErrors := 0
1574					if contextErr != nil {
1575						contextErrors = 1
1576					}
1577					profile.finishStage(&profile.Semantic.Context, contextStarted, semanticInputCount, len(contextSymbols)+len(contextRelations)+len(contextNeighbors), contextErrors)
1578				}
1579			}
1580			runtimeStarted := profile.start()
1581			runtimeTraces, runtimeErr := semanticRuntimeTraceFacts(status.Brain.Path, semanticSource, task, semanticLimit)
1582			if runtimeErr != nil {
1583				report.Warnings = append(report.Warnings, "runtime trace context unavailable: "+runtimeErr.Error())
1584			} else {
1585				report.Semantic.RuntimeTraces = runtimeTraces
1586			}
1587			if profile != nil {
1588				runtimeErrors := 0
1589				if runtimeErr != nil {
1590					runtimeErrors = 1
1591				}
1592				profile.finishStage(&profile.Semantic.RuntimeTraces, runtimeStarted, semanticInputCount, len(runtimeTraces), runtimeErrors)
1593			}
1594			if !semanticDelegated {
1595				testsStarted := profile.start()
1596				tests, testsErr := semanticTestFactsReservoir(status.Brain.Path, semanticSource, task, semanticLimit)
1597				if testsErr != nil {
1598					report.Warnings = append(report.Warnings, "test suggestions unavailable: "+testsErr.Error())
1599				} else {
1600					report.Semantic.Tests = brainBriefSelectSemanticTests(tests, report.Semantic.Context, semanticLimit)
1601				}
1602				if profile != nil {
1603					testErrors := 0
1604					if testsErr != nil {
1605						testErrors = 1
1606					}
1607					profile.finishStage(&profile.Semantic.Tests, testsStarted, semanticInputCount, len(tests.Roots)+len(tests.Suggestions), testErrors)
1608				}
1609			}
1610		} else if !semanticDelegated {
1611			providerAbsent := hostCLIOnPath() && !semanticProviderOnHost()
1612			report.Warnings = append(report.Warnings, brainBriefCodeContextWarning(graphStoreMissing, graphStoreMissingDetail, providerAbsent))
1613		}
1614		// Facts recorded outside any repository reach the brief — the surface the
1615		// agent guide mandates as the first call of every task. Loaded before the
1616		// gate because a repository that has never recorded a fact of its own has
1617		// no fact source, and that is exactly the case global facts exist for: a
1618		// preference recorded once, in a repo that has never been told it. A
1619		// damaged global store degrades to a warning rather than taking the brief
1620		// down.
1621		var briefGlobalFacts []factRecord
1622		var briefGlobalIDs map[string]bool
1623		if globalFacts, globalErr := factstore.GlobalFactsForRead(opts.Env, false); globalErr != nil {
1624			report.Warnings = append(report.Warnings, "global memories unavailable: "+globalErr.Error())
1625		} else {
