func runBrainBrief(ctx context.Context, cmd *cobra.Command, opts Options, briefOpts brainBriefOptions, task string) error {
	if briefOpts.limit <= 0 {
		return errors.New("--limit must be greater than zero")
	}
	var profile *brainBriefProfile
	if briefOpts.profileJSON != "" {
		profile = newBrainBriefProfiler()
	}
	target := agentSurfaceTarget(opts, nil)
	statusStarted := profile.start()
	status, err := buildBrainStatusReport(ctx, opts, target)
	statusErrors := 0
	if err != nil {
		statusErrors = 1
	}
	if profile != nil {
		statusOutputs := 1
		if err != nil {
			statusOutputs = 0
		}
		profile.finishStage(&profile.StatusBuildState, statusStarted, 1, statusOutputs, statusErrors)
	}
	if err != nil {
		return err
	}
	report := brainBriefReport{
		GeneratedAt: opts.Now().UTC(),
		Task:        task,
		Status:      brainBriefOutputStatus(status),
		Guidance: []string{
			"Treat the brain as an indexed snapshot, not live memory.",
			"Use likely_edit_files before text search; if search is still needed, scope it to likely_files and specific identifiers. Use likely_test_files for validation context.",
			"Use the live-state overlay before trusting code-context results for files changed in this session.",
			"Inspect full diffs or source files when the task intersects dirty files or when confidence is low.",
		},
	}
	var receiptBranch, receiptSurface string
	var receiptFactIDs []string
	// The graph plugin's store answers first (COR-2217): `graph context` reads
	// the committed-tree sqlite sidecar the graph owns, so the brief no longer
	// depends on the brain's own copy of the snapshot when the plugin can
	// serve. Plugin absent or a version without the verb falls through to the
	// internal semantic path (or its missing-index warning) unchanged; a
	// present graph with no store for this commit keeps its detail so the
	// warning can carry graph's remedy instead of stale `refresh` advice
	// (COR-2257).
	semanticDelegated := false
	graphStoreMissing := false
	var graphStoreMissingDetail string
	{
		delegationStarted := profile.start()
		graphContext, graphErr := fetchGraphTaskContext(ctx, opts.Runner, status.Repo.Root, briefOpts.graphBinary, task, briefOpts.limit, briefOpts.limit)
		if graphErr == nil && graphContext.StoreUnavailable {
			graphStoreMissing = true
			graphStoreMissingDetail = strings.TrimSpace(graphContext.Detail)
		}
		// An empty symbol list falls through too: the internal index may still
		// have an answer, and delegating nothing would also suppress the
		// missing-index warning. Commit/tree coherence needs no check here —
		// the provider keys the store by the current committed tree and
		// reports any mismatch as store_unavailable.
		// An ancestor answer whose own account of itself is inconsistent is
		// refused outright: brain would be unable to say which results are
		// incomplete, which is the only reason to accept one at all. Falling
		// through here lands on the internal semantic path, i.e. exactly what
		// happens with no graph plugin.
		if graphErr == nil && !graphContext.Stale.usable() {
			graphContext = graphTaskContext{}
			graphStoreMissing = true
			graphStoreMissingDetail = "graph answered from an ancestor commit but could not say which files it excluded; ignoring it"
		}
		if graphErr == nil && !graphContext.StoreUnavailable && len(graphContext.Symbols) > 0 {
			report.Semantic.Context = semanticContextResult{
				Symbols:   nonNil(graphContextSymbolRecords(graphContext.Symbols)),
				Relations: nonNil(graphContextRelationRecords(graphContext.Symbols, graphContext.Relations)),
			}
			report.Semantic.Tests = graphContextTestsResult(graphContext.Tests)
			report.Semantic.Source = "graph-context"
			report.Semantic.Staleness = semanticStalenessFor(graphContext.Stale, graphContext.Symbols, graphContext.Tests)
			semanticDelegated = true
			if profile != nil {
				outputs := len(graphContext.Symbols) + len(graphContext.Relations) + len(graphContext.Tests)
				profile.finishStage(&profile.Semantic.Context, delegationStarted, len(graphContext.Symbols), outputs, 0)
			}
		}
	}
	if status.Manifest != nil && status.Manifest.Sources != nil && status.Manifest.Sources.Semantic != nil {
		semanticSource := status.Manifest.Sources.Semantic
		semanticInputCount := semanticSource.Symbols + semanticSource.Relations
		semanticLimit := briefOpts.limit
		if brainBriefSemanticNeedsCurrentBoundary(report.Status) {
			// A bounded overfetch lets the current-worktree boundary refill slots
			// which stale top-ranked records would otherwise consume.
			semanticLimit = brainBriefSemanticCandidateLimit(briefOpts.limit, semanticSource.Symbols)
		}
		if !semanticDelegated {
			contextStarted := profile.start()
			contextSymbols, contextRelations, contextNeighbors, contextErr := semstore.ContextFacts(status.Brain.Path, semanticSource, task, semanticLimit, 0)
			if contextErr != nil {
				report.Warnings = append(report.Warnings, "code context unavailable: "+contextErr.Error())
			} else {
				report.Semantic.Context = brainBriefSelectSemanticContext(contextSymbols, contextRelations, contextNeighbors, task, semanticLimit)
				if len(report.Semantic.Context.Symbols) > 0 {
					impactLimit := max(40, brainBriefExpandedCandidateLimit(briefOpts.limit, 8))
					_, impactSymbols, impactRelations, impactErr := semstore.ImpactFacts(status.Brain.Path, status.Manifest.Sources.Semantic, report.Semantic.Context.Symbols[0].ID, 2, impactLimit)
					if impactErr != nil {
						report.Warnings = append(report.Warnings, "code context impact unavailable: "+impactErr.Error())
					} else {
						report.Semantic.Context = brainBriefMergeImpactContext(report.Semantic.Context, impactSymbols, impactRelations, task, briefOpts.limit)
					}
				}
			}
			if profile != nil {
				contextErrors := 0
				if contextErr != nil {
					contextErrors = 1
				}
				profile.finishStage(&profile.Semantic.Context, contextStarted, semanticInputCount, len(contextSymbols)+len(contextRelations)+len(contextNeighbors), contextErrors)
			}
		}
		runtimeStarted := profile.start()
		runtimeTraces, runtimeErr := semanticRuntimeTraceFacts(status.Brain.Path, semanticSource, task, semanticLimit)
		if runtimeErr != nil {
			report.Warnings = append(report.Warnings, "runtime trace context unavailable: "+runtimeErr.Error())
		} else {
			report.Semantic.RuntimeTraces = runtimeTraces
		}
		if profile != nil {
			runtimeErrors := 0
			if runtimeErr != nil {
				runtimeErrors = 1
			}
			profile.finishStage(&profile.Semantic.RuntimeTraces, runtimeStarted, semanticInputCount, len(runtimeTraces), runtimeErrors)
		}
		if !semanticDelegated {
			testsStarted := profile.start()
			tests, testsErr := semanticTestFactsReservoir(status.Brain.Path, semanticSource, task, semanticLimit)
			if testsErr != nil {
				report.Warnings = append(report.Warnings, "test suggestions unavailable: "+testsErr.Error())
			} else {
				report.Semantic.Tests = brainBriefSelectSemanticTests(tests, report.Semantic.Context, semanticLimit)
			}
			if profile != nil {
				testErrors := 0
				if testsErr != nil {
					testErrors = 1
				}
				profile.finishStage(&profile.Semantic.Tests, testsStarted, semanticInputCount, len(tests.Roots)+len(tests.Suggestions), testErrors)
			}
		}
	} else if !semanticDelegated {
		providerAbsent := hostCLIOnPath() && !semanticProviderOnHost()
		report.Warnings = append(report.Warnings, brainBriefCodeContextWarning(graphStoreMissing, graphStoreMissingDetail, providerAbsent))
	}
	// Facts recorded outside any repository reach the brief — the surface the
	// agent guide mandates as the first call of every task. Loaded before the
	// gate because a repository that has never recorded a fact of its own has
	// no fact source, and that is exactly the case global facts exist for: a
	// preference recorded once, in a repo that has never been told it. A
	// damaged global store degrades to a warning rather than taking the brief
	// down.
	var briefGlobalFacts []factRecord
	var briefGlobalIDs map[string]bool
	if globalFacts, globalErr := factstore.GlobalFactsForRead(opts.Env, false); globalErr != nil {
		report.Warnings = append(report.Warnings, "global memories unavailable: "+globalErr.Error())
	} else {
		briefGlobalFacts = globalFacts
	}
	if status.Sources.Facts || len(briefGlobalFacts) > 0 {
		branch := status.Live.Branch
		if branch == "" {
			branch = distillDefaultBranch
		}
		factsLoadStarted := profile.start()
		facts, factsErr := factstore.Load(status.Brain.Path)
		if profile != nil {
			factsLoadErrors := 0
			if factsErr != nil {
				factsLoadErrors = 1
			}
			profile.finishStage(&profile.Facts.Load, factsLoadStarted, 1, len(facts), factsLoadErrors)
		}
		if factsErr != nil {
			report.Warnings = append(report.Warnings, "memories unavailable: "+factsErr.Error())
		} else {
			// An empty fact set on THIS branch while other branches hold facts
			// is the single most misleading thing the brief can report: it is
			// step 1 of the shipped guide, so it is the first thing an agent
			// sees, and silence reads as "this brain knows nothing".
			if len(briefGlobalFacts) > 0 {
				facts, briefGlobalIDs = retrieval.MergeGlobalFacts(facts, briefGlobalFacts)
			}
			factsRankStarted := profile.start()
			report.Facts = rankFacts(facts, task, brainBriefFactsCount(briefOpts.limit), false)
			report.GlobalFactIDs = factscmd.SortedGlobalFactIDs(report.Facts, briefGlobalIDs)
			report.Precedent = brainBriefPrecedents(status.Brain.Path, report.Facts)
			if profile != nil {
				profile.finishStage(&profile.Facts.Rank, factsRankStarted, len(facts), len(report.Facts), 0)
			}
			receiptBranch = branch
			receiptSurface = briefOpts.surface
			if receiptSurface == "" {
				receiptSurface = "brief"
			}
			receiptFactIDs = factRecordIDs(report.Facts)
		}
	}
	likelyFilesStarted := profile.start()
	report.FactsLocusDrift = retrieval.FactsLocusDrift(status.Repo.Root, retrieval.FactsEligibleForLocusDrift(report.Facts, briefGlobalIDs))
	if len(report.GlobalFactIDs) > 0 {
		report.Guidance = append(report.Guidance, "Memories from the global store (not scoped to this repository): "+strings.Join(report.GlobalFactIDs, ", "))
	}
	// A non-current semantic index is still useful for intent and graph shape,
	// but its repository loci must cross the live worktree boundary before the
	// packet can present them as current context. The durable index is unchanged.
	if brainBriefSemanticNeedsCurrentBoundary(report.Status) {
		brainBriefFilterDepartedSemantic(status.Repo.Root, report.Status.Live, &report.Semantic)
		brainBriefCapSemantic(&report.Semantic, briefOpts.limit)
	}
	report.LikelyEditFiles, report.LikelyTestFiles, report.LikelyFiles = brainBriefLikelyFileGroups(status.Repo.Root, report, task)
	brainBriefPromotePostIndexFiles(ctx, opts.Runner, status, task, &report)
	brainBriefApplyLayoutGuidance(status.Repo.Root, task, &report)
	if profile != nil {
		likelyInputs := len(report.Semantic.Context.Symbols) + len(report.Semantic.Context.Relations) + len(report.Semantic.RuntimeTraces) + len(semanticTestSuggestionsForSynthesis(report.Semantic.Tests)) + len(report.Facts)
		profile.finishStage(&profile.Synthesis.LikelyFiles, likelyFilesStarted, likelyInputs, len(report.LikelyEditFiles)+len(report.LikelyTestFiles)+len(report.LikelyFiles), 0)
	}
	actionStarted := profile.start()
	actionInputs := len(report.LikelyFiles)
	report.ActionChecklist = brainBriefActionChecklist(status.Repo.Root, report, task)
	if len(report.ActionChecklist) > 0 {
		brainBriefPrioritizeActionTargets(status.Repo.Root, &report)
		report.Guidance = append(report.Guidance, brainBriefActionChecklistGuidance)
	} else if brainBriefPromoteGitIntentFile(ctx, opts.Runner, status.Repo.Root, task, &report) {
		brainBriefApplyLayoutGuidance(status.Repo.Root, task, &report)
		if profile != nil {
			profile.Synthesis.LikelyFiles.OutputCount = len(report.LikelyEditFiles) + len(report.LikelyTestFiles) + len(report.LikelyFiles)
		}
	}
	if profile != nil {
		profile.finishStage(&profile.Synthesis.ActionChecklist, actionStarted, actionInputs, len(report.ActionChecklist), 0)
	}
	// The private legacy stream preserves weak file/action evidence for synthesis.
	// Weak rows in the ranked reservoir are not useful enough to spend packet
	// tokens; strong late candidates already refilled it before this point.
	report.Semantic.Tests.Suggestions = visibleSemanticTestSuggestions(report.Semantic.Tests.Suggestions, briefOpts.limit)
	// The checked loaders below fail the brief on unsafe or unreadable derived
	// state instead of presenting it as empty. A genuinely absent corpus
	// is still optional and contributes nothing.
	patternsStarted := profile.start()
	views, _, perr := patterncore.LoadPatternViews(status.Brain.Path)

package cli

import (
	"fmt"
	"os"
	"sort"
	"strings"
	"time"

	"github.com/entireio/entire-brain/internal/cli/internal/base"
	"github.com/entireio/entire-brain/internal/cli/internal/brainstore"
	"github.com/entireio/entire-brain/internal/cli/internal/factstore"
	bmanifest "github.com/entireio/entire-brain/internal/cli/internal/manifest"
)

// distillCoverage reports the last recorded distillation and sessions created
// since it. Older sessions may also be unprocessed; timestamps do not prove coverage.
func distillCoverage(manifest *exportManifest) (last time.Time, undigested int, ok bool) {
	if manifest == nil || manifest.Sources == nil || manifest.Sources.Facts == nil {
		return time.Time{}, 0, false
	}
	last = manifest.Sources.Facts.LastDistilledAt
	if last.IsZero() {
		return time.Time{}, 0, false
	}
	if manifest.Sources.Sessions != nil {
		for _, s := range manifest.Sources.Sessions.Sessions {
			if s.CreatedAt.After(last) {
				undigested++
			}
		}
	}
	return last, undigested, true
}

// emptyResultBlindSpot is the one-liner appended to empty retrieval results.
// Reads the manifest and, when facts are declared, cross-checks the fact store
// behind it. Both are cheap, and this only runs on an EMPTY result — the exact
// moment the difference between "nothing was stored" and "what was stored is
// gone" decides whether the line is true.
// Empty string when nothing useful can be said (no manifest at all).
func emptyResultBlindSpot(brainDir string) string {
	return emptyResultBlindSpotOnBranch(brainDir, "")
}

// emptyResultBlindSpotOnBranch is emptyResultBlindSpot for callers that know
// which branch they queried. Facts are stored per branch, so "nothing here" and
// "nothing anywhere" are different answers and only this variant can tell them
// apart.
func emptyResultBlindSpotOnBranch(brainDir, branch string) string {
	manifest, err := bmanifest.Load(brainDir)
	// A missing manifest loads as an empty struct, not an error, and a nil
	// Sources is exactly that case: bmanifest.Normalize gives every manifest
	// it actually parsed a non-nil Sources, so only the absent-manifest path
	// reaches here with nil. That is the NO-BRAIN case, and it is the one this
	// line most needs to cover — see noBrainBlindSpot.
	if err != nil || manifest == nil || manifest.Sources == nil {
		return noBrainBlindSpot(err)
	}
	// Every branch below EXPLAINS an absence, and each explanation is false
	// when the facts were stored and the store lost them. The last one —
	// "the answer may genuinely not be in the brain" — is the most damaging
	// thing this tool can say: it tells a user their memory never existed,
	// immediately after it was destroyed. A known-lossy store must never reach
	// it, so the truth replaces the note here.
	//
	// This single choke point is why recall, search, query and retrieve all
	// inherit the correction without each having to remember to ask.
	if integrity := factstore.Inspect(brainDir, manifest.Sources.Facts); !integrity.OK() {
		return "note: this empty result is NOT evidence of absence — " + integrity.Warning()
	}
	// A connected repo whose branch never synced may be missing the whole
	// team's facts, and the remedy is one command — more actionable than "try
	// another branch", so it wins over the branch note below. The integrity
	// check above still wins: a store that lost facts is not merely unsynced.
	if note := unsyncedHostedFactsBlindSpot(brainDir, branch); note != "" {
		return note
	}
	// Facts are recorded against the branch the session ran on. Sessions run on
	// feature branches and queries run from main, so an empty result on one
	// branch is the ordinary case rather than a signal about the corpus.
	//
	// THIS IS CHECKED BEFORE THE COVERAGE NOTES, and the order is the whole
	// point. Both can be true at once, and when they are, naming the branch
	// that holds the facts is the only one the caller can act on: it ends with
	// a flag they can retype, where "coverage of older sessions is unknown"
	// ends with nothing to do.
	//
	// Checked last, this feature was unreachable in the case it was built for.
	// `undigested > 0` is true in every repository where a session has been
	// captured since the last distillation -- which is every actively worked
	// repository, and you are on a feature branch BECAUSE you have been
	// working. The fixtures never caught it because they set LastDistilledAt
	// to now with sessions two hours old, so undigested was always 0 and the
	// branch path was never exercised.
	//
	// An import with --overwrite replaced the fact layer wholesale, so facts
	// remembered here before it are gone. Every note below this point talks
	// about distillation coverage, which would send the reader to re-distill --
	// and re-distilling cannot bring back what an import replaced. Ordered
	// after the integrity and branch checks: a lost store or a wrong branch is
	// still the more precise answer when either applies.
	importedAt, imported := lastBundleImportAt(brainDir)
	last, undigested, ok := distillCoverage(manifest)
	// Only while the import is still the most recent thing that happened. It
	// stays TRUE forever -- those facts really are gone -- but it stops being
	// the most useful answer once work has been distilled since, and returning
	// it unconditionally masked coverage information permanently. Raised as a
	// finding, and correct.
	if imported && (!ok || importedAt.After(last)) {
		return fmt.Sprintf("note: a bundle import on %s replaced this brain's memory layer with the bundle's, so memories recorded here before then are no longer present; this empty result is not evidence of absence", importedAt.Format("2006-01-02"))
	}
	// Past that point the coverage note leads, but the import is still named:
	// re-distilling cannot bring back what the import replaced, and a reader
	// sent to distill without being told that would try it and find nothing.
	suffix := ""
	if imported {
		suffix = fmt.Sprintf(" (a bundle import on %s replaced the fact layer; anything recorded before then is gone whatever distillation reports)", importedAt.Format("2006-01-02"))
	}
	if !ok {
		if manifest.Sources.Sessions != nil && len(manifest.Sources.Sessions.Sessions) > 0 {
			return fmt.Sprintf("note: distillation coverage is unknown for %d captured session(s); run `"+base.BrainInvocation(os.LookupEnv, "distill")+"`", len(manifest.Sources.Sessions.Sessions)) + suffix
		}
		return "note: no distillation timestamp is recorded; run `" + base.BrainInvocation(os.LookupEnv, "refresh") + "`, then `distill`" + suffix
	}
	if undigested > 0 {
		return fmt.Sprintf("note: last distillation %s; %d session(s) captured since; coverage of older sessions is unknown", last.Format("2006-01-02"), undigested) + suffix
	}
	return fmt.Sprintf("note: last distillation %s; complete session coverage is unknown, so this empty result is not evidence of absence", last.Format("2006-01-02")) + suffix
}

// otherBranchBlindSpot moved to factstore.OtherBranchBlindSpot with the
// extracted command surface; get's miss note shares it from there.

// noBrainBlindSpot is the note for a repository whose brain does not exist or
// cannot be read.
//
// This case used to return the empty string — "nothing useful to say" — which
// inverted the whole point of the mechanism. A brain that HAS been built got a
// note explaining its empty result; a repository with no brain at all got a
// bare
//
//	{"branch":"main","query":"Hello","results":[]}
//
// so the note appeared when it was least needed and was missing when it
// mattered most. An agent reads that empty array as "the brain knows nothing
// about this" and writes the tool off, when the true answer is "there is no
// brain here yet". brain_code already refuses this state out loud ("semantic
// index missing", naming the refresh command that builds one); the text
// retrieval surface stayed silent about it.
//
// Same mechanism as every other line in this file: one `note:` string, carried
// by the existing blind_spot field on JSON responses and printed under the
// "no results" line on text ones. Nothing new is introduced.
func noBrainBlindSpot(loadErr error) string {
	if loadErr != nil {
		return "note: this repository's brain could not be read, so this empty result is not evidence of absence; run `" + base.BrainInvocation(os.LookupEnv, "status") + "` for the reason"
	}
	return "note: no brain has been built for this repository, so nothing is indexed here and this empty result is not evidence of absence; run `" + base.BrainInvocation(os.LookupEnv, "setup") + "`"
}

// otherBranchSessionBlindSpot reports captured sessions held on branches other
// than the one scanned. It is the SESSION-unit twin of otherBranchBlindSpot.
//
// Evidence recall scans canonical sessions on one branch and returns spans, not
// facts. Reusing the fact note here would attach "N active fact(s) on M other
// branch(es)" to a result that is not about facts -- a note that does not match
// the shape of the answer is the hazard the review named on the unified
// surfaces, and it applies just as much to this one.
//
// So the discipline is the same and the unit is the result's own: an empty
// evidence result on a branch holding no sessions, while other branches hold
// them, is the same wrong-branch trap and the same actionable remedy.
//
// Empty when the caller did not say which branch it scanned, when the manifest
// cannot be read, or when no other branch holds a session.
func otherBranchSessionBlindSpot(brainDir, branch string) string {
	branch = strings.TrimSpace(branch)
	if branch == "" {
		return ""
	}
	manifest, err := bmanifest.Load(brainDir)
	if err != nil || manifest == nil || manifest.Sources == nil || manifest.Sources.Sessions == nil {
		return ""
	}
	byBranch := map[string]int{}
	here := 0
	for _, session := range manifest.Sources.Sessions.Sessions {
		name := strings.TrimSpace(session.Branch)
		if name == "" {
			continue
		}
		if name == branch {
			here++
			continue
		}
		byBranch[name]++
	}
	// Sessions on THIS branch mean the scan had material to work with, so an
	// empty result is about the query, not the branch.
	if here > 0 || len(byBranch) == 0 {
		return ""
	}
	total := 0
	names := make([]string, 0, len(byBranch))
	for name, n := range byBranch {
		total += n
		names = append(names, name)
	}
	// Map iteration is randomised, so an unsorted list would differ between
	// identical runs.
	sort.Strings(names)
	return fmt.Sprintf(
		"note: no sessions were captured on %s; %d session(s) on %d other branch(es): %s — retry with --branch <name>",
		branch, total, len(names), strings.Join(names, ", "))
}

// unsyncedHostedFactsBlindSpot notes a branch that has not synced against the
// CONNECTED hosted brain: repo-level hosted.json present, per-branch
// hosted-target.json absent or recording a different target (a marker left by
// a previous connection must not suppress the note). Purely local reads; no
// network.
func unsyncedHostedFactsBlindSpot(brainDir, branch string) string {
	// The branchless surface (emptyResultBlindSpot) passes ""; facts sync per
	// branch, so there is no empty-branch marker and the note would be
	// nonsense — and would hide the coverage notes below it.
	if strings.TrimSpace(branch) == "" {
		return ""
	}
	binding, connected, err := brainstore.ReadHostedRepoBinding(brainDir)
	if err != nil || !connected || binding.OptedOut {
		return ""
	}
	if checkHostedFactsBinding(brainDir, binding.RepoID, binding.BaseURL) == nil {
		return ""
	}
	// The remedy must be a command that PULLS: `facts sync` only publishes
	// (and would write the marker that silences this note without fetching
	// anything); connect runs the full sync-and-pull.
	return "note: this repository is connected to a hosted brain but has not synced with it; run '" + base.BrainInvocation(os.LookupEnv, "connect") + "' or wait for the next daemon tick"
}

