func buildBrainStatusReportWithAvailability(ctx context.Context, opts Options, target string, lightweight bool) (brainStatusReport, error) {
	repoDir, local, err := clibase.ResolveLocalTargetRepoDir(ctx, opts.Runner, target)
	if err != nil {
		return brainStatusReport{}, err
	}
	if !local {
		return brainStatusReport{}, fmt.Errorf("status requires a local repository path: %s", target)
	}
	storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
	if err != nil {
		return brainStatusReport{}, err
	}
	generatedAt := opts.Now().UTC()
	manifestState := "current"
	manifestSchema := bmanifest.SchemaVersion
	var manifest *exportManifest
	var healthIssues []memoryHealthIssue
	if lightweight {
		var health memoryManifestHealth
		var issue *memoryHealthIssue
		manifest, health, issue = inspectBrainManifestHealth(storage.BrainDir)
		manifestState = health.State
		manifestSchema = health.SchemaVersion
		if issue != nil {
			healthIssues = append(healthIssues, *issue)
		}
	} else {
		manifest, err = bmanifest.Load(storage.BrainDir)
		if err != nil {
			return brainStatusReport{}, err
		}
		manifestSchema = manifest.SchemaVersion
	}
	// Old layouts are reported without hiding the other Brain sources. Graph is
	// optional: retain all non-code Brain sources when it is absent, and "not
	// installed" / "not indexed yet" stay silent here exactly as before (they
	// already surface through the missing-semantic-index messaging below). A
	// store that Graph IS able to describe but that this build cannot actually
	// use -- a version mismatch, a corrupt descriptor, a command that failed
	// outright -- is a different, actionable problem, and used to vanish along
	// with the ordinary case. That one is recorded as a warning instead.
	var graphStatusWarning string
	if layoutErr := checkLegacyBrainLayout(storage.BrainDir, manifest); layoutErr != nil {
		graphStatusWarning = layoutErr.Error()
		code := brainstore.MemoryErrorCode(layoutErr)
		if errors.Is(layoutErr, errLegacyBrainLayout) {
			code = brainstore.UnsupportedVersionCode
		}
		healthIssues = append(healthIssues, memoryHealthIssue{Kind: "brain_layout", Code: code, Action: layoutErr.Error()})
	}
	if manifest != nil {
		if manifest.Sources == nil {
			manifest.Sources = &brainSources{}
		}
		profile := graphStoreProfile(manifest)
		manifest.Sources.Semantic = nil
		// Do not replace the old source with a healthy Graph descriptor.
		if graphStatusWarning == "" {
			if d, graphErr := fetchGraphStore(ctx, opts, repoDir, "", profile); graphErr != nil {
				if !errors.Is(graphErr, errGraphStoreUnsupported) && !errors.Is(graphErr, errGraphStoreUnavailable) {
					graphStatusWarning = "graph store unavailable: " + graphErr.Error()
				}
			} else {
				manifest.Sources.Semantic = semstore.GraphStoreSource(d, storage.BrainDir)
			}
		}
	}
	report := brainStatusReport{
		GeneratedAt: generatedAt,
		Repo:        brainStatusRepo{Root: repoDir, Key: storage.Key},
		Brain: brainStatusBrain{
			Path:            storage.BrainDir,
			Schema:          manifestSchema,
			SupportedSchema: bmanifest.SchemaVersion,
			ManifestState:   manifestState,
		},
		Manifest: manifest,
		Issues:   healthIssues,
	}
	if graphStatusWarning != "" {
		report.Warnings = append(report.Warnings, graphStatusWarning)
	}
	if lightweight {
		report.Integrity = "not_checked"
	}
	if manifest != nil && !manifest.GeneratedAt.IsZero() {
		report.Brain.GeneratedAt = manifest.GeneratedAt.Format(time.RFC3339)
	}
	if manifest != nil && manifest.Sources != nil {
		report.Sources.Seed = manifest.Sources.Seed != nil
		report.Sources.Sessions = manifest.Sources.Sessions != nil
		report.Sources.Semantic = manifest.Sources.Semantic != nil
		report.Sources.History = manifest.Sources.History != nil
		report.Sources.Facts = manifest.Sources.Facts != nil
		if f := manifest.Sources.Facts; f != nil {
			report.Facts = &brainStatusFacts{
				Facts:      f.Facts,
				Distilled:  f.Distilled,
				Authored:   f.Authored,
				Imported:   f.Imported,
				Superseded: f.Superseded,
				Branches:   len(f.Branches),
				Proposals:  f.Proposals,
			}
			// One flat store: both paths cross-check declared vs readable (the
			// fold is one store read; the old lightweight shortcut existed to
			// avoid walking hundreds of branch files).
			integrity := factstore.Inspect(storage.BrainDir, f)
			if !integrity.OK() {
				if !lightweight {
					report.Facts.Integrity = &integrity
				}
				report.Warnings = append(report.Warnings, integrity.Warning())
			}
		}
		if sem := manifest.Sources.Semantic; sem != nil {
			report.Semantic = &brainStatusSemantic{
				Provider: &brainStatusSemanticProvider{
					Name:         sem.Provider,
					Version:      sem.ProviderVersion,
					Schema:       sem.SchemaVersion,
					Snapshot:     sem.SnapshotPath,
					Store:        "graph-owned",
					Capabilities: sortedStringCopy(sem.Capabilities),
				},
			}
		}
		report.Sources.Docs = manifest.Sources.Docs != nil
	}
	hosted, hostedWarning := buildHostedStatus(storage.BrainDir, opts.Now().UTC())
	report.Hosted = hosted
	if hostedWarning != "" {
		report.Warnings = append(report.Warnings, hostedWarning)
	}
	live, liveErr := brainLiveStateReport(ctx, opts.Runner, repoDir, manifest)
	if liveErr != nil {
		report.Warnings = append(report.Warnings, "live state unavailable: "+liveErr.Error())
	} else {
		report.Live = live
	}
	if manifest != nil && manifest.Sources != nil && (manifest.Sources.Seed != nil || manifest.Sources.Docs != nil) {
		report.Retrieval = buildBrainRetrievalStatus(ctx, opts.Runner, storage.BrainDir, repoDir, manifest, report.Live, !lightweight)
		if report.Retrieval != nil {
			if lightweight && manifest.Sources.History != nil {
				h := manifest.Sources.History
				report.Retrieval.Conversation = &brainStatusConversation{Exchanges: h.Exchanges, IncompleteExchanges: h.IncompleteExchanges, VectorState: "not_checked"}
			} else {
				report.Retrieval.Conversation = buildConversationStatus(report.Brain.Path, manifest)
			}
		}
	}
	if report.Semantic != nil {
		freshness, freshnessErr := semanticFreshnessReport(ctx, opts, repoDir, !lightweight)
		if freshnessErr != nil {
			report.Warnings = append(report.Warnings, "freshness unavailable: "+freshnessErr.Error())
		} else {
			report.Semantic.Freshness = &freshness
		}
	}
	// Read the identities a previous `setup` chose, so a custom-named watcher
	// is inspected rather than reported missing.
	recordedSetupOpts, _, _ := setupOptionsFromRecord(filepath.Dir(storage.HeadPath))
	onboarding := buildBrainOnboardingStatus(ctx, opts, storage, manifest, recordedSetupOpts)
	// The repo root from the REPORT, not opts.Env: the latter is empty on the
	// ordinary `status` path, which is why the first version of this check
	// never fired. report.Repo.Root is the resolved root this status is about.
	if root := strings.TrimSpace(report.Repo.Root); root != "" {
		if wired, missing := agentsetup.AgentsWired(root); !wired {
			onboarding.AgentsUnwired = true
			onboarding.AgentsMissing = missing
			// Keep the published JSON shape while exposing the same repair
			// diagnostic to JSON consumers through warnings.
			report.Warnings = append(report.Warnings, "agents not wired: missing "+strings.Join(missing, ", ")+"; run "+clibase.SetupCommandPrefix(os.LookupEnv)+" setup so your agent uses this brain")
		}
	}
	markMissingDeclaredIndexes(&onboarding, storage.BrainDir, manifest)
	report.Onboarding = &onboarding
	if clibase.BackgroundPaused(opts.Env) {
		report.Warnings = append(report.Warnings, "background work is paused, so this brain is not updating — `"+clibase.SetupCommandPrefix(os.LookupEnv)+" start` resumes it")
	}
	return report, nil
}

