41			if strings.Contains(detail, "unknown command") || strings.Contains(detail, "unknown subcommand") {
42				return graphStoreDescriptor{}, errGraphStoreUnsupported
43			}
44			return graphStoreDescriptor{}, fmt.Errorf("Graph read-only store unavailable: %w: %s", err, firstLine(strings.TrimSpace(string(stderr))))
45		}
