52		}
53		// A contract mismatch names the binary that is behind: a NEWER contract than
54		// this build supports means Graph has moved on and entire-brain must catch
55		// up; an OLDER contract means the installed Graph predates the interface
56		// brain needs, so Graph is the one to upgrade. Both are a present, responding
57		// Graph reporting an incompatible version -- distinct from errGraphStoreUnsupported,
58		// which means Graph never answered the store command at all (effectively
59		// absent) and is handled separately above.
60		if d.ContractVersion > graphStoreSupportedContract {
61			return d, fmt.Errorf("%w (Graph reports store contract %d, this build supports %d)", errGraphStoreContractNewer, d.ContractVersion, graphStoreSupportedContract)
62		}
63		if d.ContractVersion != graphStoreSupportedContract {
64			return d, fmt.Errorf("%w (Graph reports store contract %d, this build requires %d)", errGraphStoreContractOlder, d.ContractVersion, graphStoreSupportedContract)
65		}
66		if err := semstore.ValidateSchema(d.Header.SchemaVersion); err != nil {
67			// semstore.ValidateSchema's own text names what this build reads but not
68			// who's asking; naming both Graph (the header's source) and entire-brain
69			// (what rejected it) here matches the other version-mismatch messages in
70			// this file.
71			return d, fmt.Errorf("Graph's semantic schema is unsupported by this entire-brain build: %w", err)
72		}
