130	func runGraphOwnedIndex(ctx context.Context, cmd *cobra.Command, opts Options, indexOpts semanticIndexOptions, target string) error {
131		if ctx == nil {
132			ctx = context.Background()
133		}
134		if indexOpts.worktree {
135			return errors.New("Graph owns the committed-tree index; use entire graph query without --head to inspect uncommitted code")
136		}
137		repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, target)
138		if err != nil {
139			return err
140		}
141		if !local {
142			return fmt.Errorf("index requires a local repository: %s", target)
143		}
144		if err = enforceIndexContainment(indexOpts.containRoot, repoDir); err != nil {
145			return err
146		}
147		if _, err := base.GitScalar(ctx, opts.Runner, repoDir, "rev-parse", "HEAD"); err != nil {
148			return nameDegenerateRepoFailure(ctx, opts.Runner, repoDir, fmt.Errorf("resolve HEAD for Graph index: %w", err))
149		}
150		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
151		if err != nil {
152			return err
153		}
154		if indexOpts.outputExplicit {
155			storage.BrainDir, err = filepath.Abs(indexOpts.outputDir)
156			if err != nil {
157				return err
158			}
159		}
160		if err := requireCurrentBrainLayout(storage.BrainDir); err != nil {
161			return err
162		}
163		binary := indexOpts.graphBinary
164		if binary == "" {
165			binary = indexOpts.semBinary
166		}
167		if binary == "" {
168			binary = "entire"
169		}
170		if indexOpts.skipGraph || indexOpts.skipSem {
171			return semanticProviderAbsentError{err: errors.New("Graph was explicitly disabled")}
172		}
173		doctor, warnings := runSemanticDoctor(ctx, opts.Runner, repoDir, binary)
174		if !doctor.NoEgress {
175			return semanticDoctorFailureError(binary, warnings)
176		}
177		profile := indexOpts.profile
178		if profile == "" {
179			profile = "full"
180		}
181		args := []string{"graph", "index", "--repo", repoDir, "--head", "--profile", profile, "--format", "json"}
182		if indexOpts.force {
183			args = append(args, "--force")
184		}
185		ignores, err := semanticProviderIgnoreFiles(repoDir)
186		if err != nil {
187			return err
188		}
189		for _, ignore := range ignores {
190			args = append(args, "--ignore-file", ignore)
191		}
192		runner, ok := opts.Runner.(EnvironmentCommandRunner)
193		if !ok {
194			return errors.New("Graph indexing requires a runner supporting per-command environment")
195		}
196		// Fail fast with the clear, specific message instead of letting an
197		// incompatible Graph run the real index command and surface a muddier
198		// binary-sourced error. Covers both directions reported by an installed
199		// Graph that actually answered (errGraphStoreContractOlder) and the case
200		// where it didn't answer at all (errGraphStoreUnsupported, Graph absent).
201		// errGraphStoreContractNewer is deliberately not fail-fasted here: Graph
202		// is ahead, not broken, and the real index command is Graph's own concern.
203		if _, probeErr := fetchGraphStore(ctx, opts, repoDir, binary, profile); errors.Is(probeErr, errGraphStoreUnsupported) || errors.Is(probeErr, errGraphStoreContractOlder) {
