214		if err != nil {
215			return fmt.Errorf("Graph index: %w: %s", err, firstLine(strings.TrimSpace(string(stderr))))
216		}
217		d, err := fetchGraphStore(ctx, opts, repoDir, binary, profile)
218		if err != nil {
219			return err
220		}
221		unlock, err := acquireSemanticIndexLock(storage.BrainDir)
222		if err != nil {
223			return err
224		}
225		defer unlock()
226		// Recheck after taking the writer lock before publishing a new source.
227		if err = requireCurrentBrainLayout(storage.BrainDir); err != nil {
228			return err
229		}
230		source := semstore.GraphStoreSource(d, storage.BrainDir)
231		source.StorePath = ""
232		source.GeneratedAt = opts.Now().UTC()
233		source.Profile = profile
234		source.GraphRepoRoot = repoDir
